package app.gendragoon.cloudssd.mobile;
import java.nio.file.*;
import java.util.*;
import org.json.*;

/** Standalone JDK test with public dummy data; no Android or live credentials. */
public final class PortableVaultVectorProbe {
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception{JSONObject fixture=new JSONObject(Files.readString(Path.of(args[0])));char[] password=fixture.getString("password").toCharArray();String receiver=fixture.getString("receiverId");byte[] envelope=fixture.getJSONObject("envelope").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);PortableVault.Keys opened=PortableVault.open(envelope,password,receiver);require(opened.secret.equals(fixture.getString("storageSecret")),"Cross-language storage credential differs");require(Arrays.equals(opened.keymap,PortableVault.decode(fixture.getString("keymap"),PortableVault.MAX_KEYMAP)),"Cross-language KXAI bytes differ");byte[] sealed=PortableVault.seal(opened,password);PortableVault.Keys again=PortableVault.open(sealed,password,receiver);require(Arrays.equals(again.keymap,opened.keymap),"JCE roundtrip differs");int rejected=0;try{PortableVault.open(envelope,"wrong-password-1234".toCharArray(),receiver);}catch(Exception expected){rejected++;}try{PortableVault.open(envelope,password,"f".repeat(64));}catch(Exception expected){rejected++;}JSONObject tampered=new JSONObject(new String(envelope,java.nio.charset.StandardCharsets.UTF_8));byte[] ciphertext=PortableVault.decode(tampered.getString("ciphertext"),PortableVault.MAX_PLAIN+16);ciphertext[5]^=1;tampered.put("ciphertext",PortableVault.encode(ciphertext));try{PortableVault.open(tampered.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),password,receiver);}catch(Exception expected){rejected++;}try{PortableVault.decode("AAAA=",100);}catch(Exception expected){rejected++;}byte[] hardware=Arrays.copyOf(opened.keymap,96);hardware[4]=4;try{PortableVault.keymap(hardware);}catch(Exception expected){rejected++;}require(rejected==5,"Tamper/cross-account/encoding/hardware rejections were incomplete");Arrays.fill(password,'\0');Arrays.fill(opened.keymap,(byte)0);System.out.println("PASS JCE/Mac portable-vault vector, roundtrip and 5 negative boundaries; no live credentials");}
}
